publish('post/where-to-get-hair-extensions-or-hair-restoration-services-in-pittsburgh','Hair Extensions vs Hair Restoration in Pittsburgh','Understand the difference between cosmetic extensions and medical hair restoration, and the questions to ask before choosing a Pittsburgh provider.',
paras('Hair extensions and hair restoration answer different questions. Extensions add cosmetic length or fullness using attached or temporary hair. Medical hair-loss evaluation investigates why hair is thinning and which treatment may be appropriate. A salon extension consultation is not a diagnosis or a promise of regrowth.','If you are deciding what to book in Pittsburgh, begin with your concern: do you want a different appearance, or have you noticed unexplained thinning or shedding? New hair loss and persistent scalp symptoms should be assessed by a dermatologist.')+
section('When to speak with a dermatologist',paras('The American Academy of Dermatology explains that hair loss has many causes. Identifying the cause helps determine treatment. A cosmetic service should not be described as a substitute for that assessment.','See the <a href="https://www.aad.org/public/diseases/hair-loss/treatment/tips">AAD hair-loss guidance</a>. If you already have medical advice, follow it and ask your clinician about cosmetic services when necessary.'))+
section('What an extension consultation should clarify',ul(['Your goal: added length, fullness or a temporary event look.','Your natural hair density, condition and current styling routine.','Which methods are currently offered and whether your hair is suitable.','The amount of hair proposed and how it would blend with your cut.','The installation, upkeep, removal and full estimate.']))+
section('Avoid judging suitability from a photograph',paras('An extension result in a gallery does not show every starting condition. Ask to see work relevant to your texture and goal, but let the stylist assess suitability before purchasing hair or reserving installation. Do not assume a method described as lightweight is automatically appropriate for fine or fragile hair.','Ask what discomfort, slipping or tangling should prompt you to contact the salon. Follow method-specific care directions and arrange professional removal rather than treating the service as a one-time purchase.'))+
section('Plan the ongoing commitment',paras('The first appointment is only part of the decision. Ask how maintenance is scheduled, what each visit includes and when replacement hair or removal may be needed. Discuss the budget across the period you intend to wear the extensions.','Use <a href="/blog/hair-extensions-budget-pittsburgh">the extension budget checklist</a> and explore <a href="/services/hair-extensions-pittsburgh">Craft Collective extension services</a>. Confirm current methods and stylist availability at the actual North Hills or Canonsburg studio.')),True)

# Consolidate overlapping articles, preserving each legacy URL with a permanent redirect.
merges={
'/post/how-much-does-balayage-and-highlights-cost-in-pittsburgh':'/post/how-much-does-balayage-highlights-or-color-cost-in-pittsburgh-salons',
'/post/the-role-of-trims-in-growing-healthy-hair-in-north-hills-pittsburgh':'/post/why-regular-haircuts-matter-for-healthy-hair-in-north-hills-pittsburgh',
'/post/north-hills-hair-care-routines-that-actually-work':'/post/how-to-build-a-healthy-hair-care-routine-in-north-hills-pittsburgh',
'/post/the-importance-of-professional-consultations-in-north-hills-pittsburgh':'/post/why-professional-consultations-make-all-the-difference-in-north-hills-pittsburgh'}
tracked=subprocess.check_output(['git','ls-files'],cwd=R,text=True).splitlines()
prior_manifest=R/'scripts/content-oct2026-manifest.json'
cleaned=json.loads(prior_manifest.read_text()).get('editorial_cleanup',[]) if prior_manifest.exists() else []
for f in tracked:
    if not f.endswith('.html'):continue
    p=R/f
    if not p.exists():continue
    s=p.read_text();before=s
    if f.startswith('post/'):
        s=re.sub(r'<p\b[^>]*>(?:(?!</p>).)*(?:Cross-Link Summary|Local Anchors|SEO Keywords|Internal Links:)(?:(?!</p>).)*</p>','',s,flags=re.S|re.I)
        if s!=before and '/'+str(p.parent.relative_to(R)) not in cleaned:cleaned.append('/'+str(p.parent.relative_to(R)))
    if f.startswith('blog/archive/'):
        for src in merges:
            s=re.sub(r'<li\b[^>]*>(?:(?!</li>).)*href="'+re.escape(src)+r'"(?:(?!</li>).)*</li>','',s,flags=re.S)
    for src,dest in merges.items():s=s.replace('href="'+src+'"','href="'+dest+'"').replace('href="'+D+src+'"','href="'+D+dest+'"')
    if s!=before:p.write_text(s)
configpath=R/'vercel.json';cfg=json.loads(configpath.read_text());known={x['source'] for x in cfg['redirects']}
for src,dest in merges.items():
    if src not in known:cfg['redirects'].append({'source':src,'destination':dest,'permanent':True})
    p=R/src.lstrip('/')/'index.html'
    if p.exists():p.unlink()
configpath.write_text(json.dumps(cfg,indent=2)+'\n')

# Add curated discovery paths to hubs and relevant service pages.
new=[r for r in records if r['action']=='new']
listing='<section class="archive-body" aria-labelledby="planning-oct2026"><h2 id="planning-oct2026">Practical Pittsburgh salon planning</h2><p>Choose a guide that answers your next booking question, then confirm the individual plan with your stylist.</p><ul class="archive-list">'+''.join('<li><h3><a href="'+r['path']+'">'+html.escape(r['title'])+'</a></h3></li>' for r in new)+'</ul></section>'
for f in ['blog/index.html','guides/index.html']:
    p=R/f;s=p.read_text();s=re.sub(r'<!-- cc:planning2026 -->.*?<!-- /cc:planning2026 -->','',s,flags=re.S)
    s=s.replace('<footer>','<!-- cc:planning2026 -->'+listing+'<!-- /cc:planning2026 --><footer>');p.write_text(s)
for slug,links in {
'balayage-pittsburgh':['/blog/how-long-balayage-appointment-pittsburgh','/blog/color-maintenance-calendar-pittsburgh'],
'highlights-pittsburgh':['/blog/what-hair-color-service-to-book-pittsburgh','/blog/color-maintenance-calendar-pittsburgh'],
'hair-color-pittsburgh':['/blog/box-dye-to-blonde-pittsburgh','/blog/what-hair-color-service-to-book-pittsburgh','/reviews/color-and-extensions'],
'hair-extensions-pittsburgh':['/blog/hair-extensions-budget-pittsburgh','/reviews/color-and-extensions'],
'haircuts-pittsburgh':['/blog/salon-consultation-photos-pittsburgh','/reviews/haircuts-and-curls']}.items():
    p=R/'services'/slug/'index.html';s=p.read_text();s=re.sub(r'<!-- cc:planning2026 -->.*?<!-- /cc:planning2026 -->','',s,flags=re.S)
    titles={r['path']:r['title'] for r in records}
    sec='<section class="content-section"><div class="content-inner"><h2 class="section-headline">Plan your appointment</h2><ul class="prose">'+''.join('<li><a href="'+u+'">'+html.escape(titles[u])+'</a></li>' for u in links)+'</ul></div></section>'
    s=s.replace('<footer>','<!-- cc:planning2026 -->'+sec+'<!-- /cc:planning2026 --><footer>');p.write_text(s)
p=R/'reviews/index.html';s=p.read_text();s=re.sub(r'<!-- cc:reviewtopics -->.*?<!-- /cc:reviewtopics -->','',s,flags=re.S)
reviewsec='<section class="content-section"><div class="content-inner"><h2 class="section-headline">Explore feedback for your next service</h2><p class="prose">Read existing client feedback alongside practical consultation questions. Individual reviews describe personal experiences; confirm current pricing, stylist availability and your plan with the salon.</p><ul class="prose"><li><a href="/reviews/color-and-extensions">Color and extension reviews and consultation questions</a></li><li><a href="/reviews/haircuts-and-curls">Haircut and curly hair reviews and planning questions</a></li></ul></div></section>'
s=s.replace('<div class="reviews-grid">','<!-- cc:reviewtopics -->'+reviewsec+'<!-- /cc:reviewtopics --><div class="reviews-grid">',1);p.write_text(s)

# Remove consolidated routes from every active sitemap; add curated pages once.
NS='http://www.sitemaps.org/schemas/sitemap/0.9';ET.register_namespace('',NS)
seen_sitemap_urls=set()
for name in ['pages-sitemap.xml','blog-posts-sitemap.xml','blog-categories-sitemap.xml','site-pages-sitemap.xml']:
    p=R/name;tree=ET.parse(p);root=tree.getroot()
    for e in list(root):
        loc=e.find('{'+NS+'}loc')
        if loc is not None:
            if loc.text.removeprefix(D) in merges or loc.text in seen_sitemap_urls:root.remove(e)
            else:seen_sitemap_urls.add(loc.text)
    if name=='site-pages-sitemap.xml':
        locs={e.text for e in root.findall('.//{'+NS+'}loc')}
        for r in new:
            if D+r['path'] not in locs:
                e=ET.SubElement(root,'{'+NS+'}url');ET.SubElement(e,'{'+NS+'}loc').text=D+r['path'];ET.SubElement(e,'{'+NS+'}lastmod').text=DATE
    for e in root:
        loc=e.find('{'+NS+'}loc')
        if loc is not None and loc.text.removeprefix(D) in {r['path'] for r in records}:
            last=e.find('{'+NS+'}lastmod')
            if last is None:last=ET.SubElement(e,'{'+NS+'}lastmod')
            last.text=DATE
    tree.write(p,encoding='UTF-8',xml_declaration=True)
(R/'scripts/content-oct2026-manifest.json').write_text(json.dumps({'pages':records,'redirects':merges,'editorial_cleanup':cleaned},indent=2)+'\n')
print(json.dumps({'new':len(new),'improved':len(records)-len(new),'consolidated':len(merges),'cleaned':len(cleaned),'words':{r['path']:r['words'] for r in records}},indent=2))

# Every testimonial now has a directly verified Google source, checked October 1.
proof=json.loads((R/'scripts/verified-google-reviews.json').read_text())
for review in proof['reviews']:
    for path in ['reviews/color-and-extensions','reviews/haircuts-and-curls']:
        p=R/path/'index.html';s=p.read_text()
        s=s.replace('<cite>'+html.escape(review['short'])+' · Google review excerpt</cite>','<cite>'+html.escape(review['name'])+' · <a href="'+review['url']+'" target="_blank" rel="noopener noreferrer">Google review excerpt</a></cite>')
        p.write_text(s)
    for f in ['reviews/index.html','index.html']:
        p=R/f;s=p.read_text()
        for prefix in ['review','testimonial']:
            pattern=r'(<p class="'+prefix+'-name">'+re.escape(review['short'])+r'</p>\s*<p class="'+prefix+'-detail">).*?(</p>)'
            s=re.sub(pattern,lambda m:m[1]+'<a href="'+review['url']+'" target="_blank" rel="noopener noreferrer">Read this review on Google</a>'+m[2],s,flags=re.S)
        p.write_text(s)
for f in tracked:
    p=R/f
    if f.endswith('.html') and p.exists():
        s=p.read_text();updated=s.replace('809 reviews','834 reviews').replace('809 client reviews','834 client reviews')
        if updated!=s:p.write_text(updated)
for f in ['index.html','reviews/index.html']:
    p=R/f;s=p.read_text()
    s=re.sub(r'<!-- cc:reviewchecked -->.*?<!-- /cc:reviewchecked -->','',s,flags=re.S)
    s=s.replace('<span class="reviews-source-figure">5.0 from 834 reviews</span>','<span class="reviews-source-figure">5.0 from 834 reviews</span><!-- cc:reviewchecked --><p class="reviews-source-copy">Google rating and displayed review sources checked October 1, 2026.</p><!-- /cc:reviewchecked -->')
    p.write_text(s)
